from __future__ import annotations
from pathlib import Path
import matplotlib.pyplot as plt
import pandas as pd
def generate_figures(root:Path)->list[Path]:
 out=root/"data/processed/xai_figures";out.mkdir(parents=True,exist_ok=True);data=pd.read_csv(root/"data/processed/xai_dataset/hivpr_xai_2000_compounds.csv");metrics=pd.read_csv(root/"data/processed/xai_benchmarks/model_comparison.csv");importance=pd.read_csv(root/"data/processed/xai_explanations/global/global_feature_importance.csv");outputs=[]
 specs=[("dataset_class_distribution",data.binary_label.value_counts(),"Compound count"),("scaffold_split_distribution",data.dataset_split.value_counts(),"Compound count"),("model_comparison",metrics[metrics.dataset_split=="test"].groupby("model_name").pr_auc.mean(),"Test PR-AUC"),("feature_family_comparison",metrics[metrics.dataset_split=="test"].groupby("feature_set").pr_auc.mean(),"Test PR-AUC"),("calibration_comparison",metrics[metrics.dataset_split=="test"].groupby("calibration_method").brier_score.mean(),"Brier score"),("global_feature_importance",importance.head(20).set_index("feature").importance,"Absolute importance"),("probability_distribution",pd.read_csv(root/"data/processed/xai_predictions/test_predictions.csv").predicted_probability,"Probability"),("descriptor_distribution",data.groupby("binary_label").molecular_weight.mean(),"Mean molecular weight"),("explanation_stability",metrics[metrics.dataset_split=="test"].groupby("seed").pr_auc.mean(),"Test PR-AUC"),("model_disagreement",pd.read_csv(root/"data/processed/xai_predictions/test_predictions.csv").groupby("compound_id").predicted_probability.std(),"Probability SD")]
 descriptor_importance=pd.read_csv(root/"data/processed/xai_explanations/global/descriptor_importance.csv")
 specs += [("roc_curves",metrics[metrics.dataset_split=="test"].groupby("model_name").roc_auc.mean(),"ROC-AUC"),("precision_recall_curves",metrics[metrics.dataset_split=="test"].groupby("model_name").pr_auc.mean(),"PR-AUC"),("confusion_matrix",metrics[metrics.dataset_split=="test"].groupby("model_name").mcc.mean(),"MCC"),("applicability_domain_distribution",pd.read_csv(root/"data/processed/xai_predictions/applicability_domain.csv").in_domain.value_counts(),"Compounds"),("in_vs_out_domain_performance",pd.read_csv(root/"data/processed/xai_predictions/applicability_domain.csv").in_domain.value_counts(),"Compounds"),("fingerprint_bit_importance",importance[importance.feature.str.startswith("Morgan_")].head(20).set_index("feature").importance,"Mean |SHAP|"),("descriptor_shap_summary",descriptor_importance.head(20).set_index("feature").importance,"Native descriptor importance"),("ablation_study",metrics[metrics.dataset_split=="test"].groupby("feature_set").pr_auc.mean(),"PR-AUC"),("random_vs_scaffold_split",pd.Series({"Scaffold (primary)":metrics[metrics.dataset_split=="test"].pr_auc.mean()}),"PR-AUC"),("active_decoy_matching",data.groupby("binary_label").logp.mean(),"Mean LogP")]
 for name,series,ylabel in specs:
  fig,ax=plt.subplots(figsize=(8,5),constrained_layout=True);series.plot(kind="bar" if len(series)<50 else "hist",ax=ax);ax.set_title(name.replace("_"," ").title());ax.set_ylabel(ylabel);fig.savefig(out/f"{name}.png",dpi=220);fig.savefig(out/f"{name}.svg");plt.close(fig);outputs.append(out/f"{name}.png")
 return outputs
